/**********************************************************************
 * FILE NAME: landing.c
 *
 * PURPOSE:
 *   Lunar landing lane against the real AGC code (yaAGC oracle).
 *   Inputs and expected words: tools/oracle/cases/landing.spec / .txt
 *   (Luminary099), generated by tools/oracle/cases/gen/gen_landing.py.
 *   One P63/P64 guidance pass (RGVGCALC, TTF/8CL + ROOTPSRS, TDISPSET,
 *   QUADGUID, AFCCALC), CGCALC, THROTTLE (five throttle regions and the
 *   P66 FWEIGHT period), FINDCDUW (gimbal angles and thrust-direction
 *   filter outside PNGCS auto), ATMAG -> ASCENT -> P12RET, and RODCOMP
 *   up to THROTTLE +3.
 *
 *   Tolerances (LSB of the AGC word): see docs/modules/oracle-cases.md
 *   and docs/modules/review-guid-landing.md.
 *
 * AGC SOURCE:
 *   Luminary099 THROTTLE_CONTROL_ROUTINES.agc, LUNAR_LANDING_GUIDANCE_
 *   EQUATIONS.agc, FINDCDUW--GUIDAP_INTERFACE.agc, ASCENT_GUIDANCE.agc,
 *   P12.agc
 *
 * EXTERNAL VARIABLES:
 *   none (the lane erasables through agc_lm_pad(), agc_lm_ldg(),
 *   agc_lm_thr(), agc_lm_asc())
 *
 * EXTERNAL REFERENCES:
 *   oracle_txt.h (case files), the guid-landing lane entry points
 *
 * ABNORMAL TERMINATION CONDITIONS, ALARMS:
 *   exit status 1 when a comparison fails (oracle_finish)
 **********************************************************************/
#include <stdio.h>

#include "agc/core/assert.h"
#include "agc/core/channels.h"
#include "agc/core/flags_lm.h"
#include "agc/core/interp.h"
#include "agc/core/state.h"
#include "agc/exec/exec.h"
#include "agc/guidance/guidance.h"
#include "agc/io/dsky.h"
#include "agc/lm/landing.h"
#include "oracle_txt.h"

static agc_mat_t mat_in(const char *t, const char *name);
static void      target_in(const char *t, const char *name, agc_lm_target_t *g);
static void      common_in(const char *t);
static void      guid_pass(const char *t, long int tol);
static void      cgcalc(const char *t, long int tol);
static void      throttle(const char *t);
static void      findcduw(const char *t, long int tol);
static void      ascent(const char *t);
static void      rodcomp(const char *t);

/**********************************************************************
 * AGC: none -- run every case; the exit status reports failures.
 *
 * RETURNS: int -- 0 when every comparison passed (or SKIP), else 1
 **********************************************************************/
int main(void)
{
    if (!oracle_load("landing"))
    {
        (void) printf("oracle_landing: SKIP (case files not found)\n");

        return (0);
    }

    guid_pass("guid_brak_a", 4);
    guid_pass("guid_brak_b", 4);
    guid_pass("guid_appr", 4);
    cgcalc("cgcalc_brak", 0);
    cgcalc("cgcalc_appr", 0);
    throttle("throt_mid");
    throttle("throt_old");
    throttle("throt_up");
    throttle("throt_hold");
    throttle("throt_down");
    throttle("throt_p66");
    findcduw("findcduw_a", 0);
    findcduw("findcduw_b", 0);
    ascent("ascent_a");
    ascent("ascent_b");
    rodcomp("rodcomp_a");
    rodcomp("rodcomp_b");

    return (oracle_finish("oracle_landing"));
}

/**********************************************************************
 * AGC: none -- AGC_ASSERT report hook: print the failure.
 *
 * ARGUMENTS:
 *   file  const char *  I    source file of the assertion
 *   line  int           I    source line
 *   expr  const char *  I    the asserted expression
 *
 * RETURNS: bool -- false (the assertion stays failed)
 **********************************************************************/
bool agc_assert_report(const char *file, int line, const char *expr)
{
    (void) printf("assert %s:%d %s\n", file, line, expr);

    return (false);
}

/**********************************************************************
 * AGC: none -- a 3x3 matrix input (three row vectors) of a case.
 *
 * ARGUMENTS:
 *   t     const char *  I    case tag
 *   name  const char *  I    erasable name of row 0
 *
 * RETURNS: agc_mat_t -- the matrix, half unit
 **********************************************************************/
static agc_mat_t mat_in(const char *t, const char *name)
{
    agc_mat_t m; /* the matrix, half unit */

    for (int r = 0; r < 3; r++)
    {
        m.row[r] = oracle_in_vec_at(t, name, r);
    }

    return (m);
}

/**********************************************************************
 * AGC: none -- the 28-word target block set as `name` (RBRFG, or
 * RBRFG+28 = RAPFG).
 *
 * ARGUMENTS:
 *   t     const char *       I    case tag
 *   name  const char *       I    erasable name of the block
 *   g     agc_lm_target_t *  O    target set
 **********************************************************************/
static void target_in(const char *t, const char *name, agc_lm_target_t *g)
{
    const int base = 0; /* word offset of the block */

    for (int c = 0; c < 3; c++)
    {
        g->rfg.c[c] = oracle_in_dp(t, name, base + 2 * c);
        g->vfg.c[c] = oracle_in_dp(t, name, base + 6 + 2 * c);
        g->afg.c[c] = oracle_in_dp(t, name, base + 12 + 2 * c);
    }

    g->vfg_star = oracle_in_dp(t, name, base + 18);
    g->afg_star = oracle_in_dp(t, name, base + 20);
    g->jfg_star = oracle_in_dp(t, name, base + 22);
    g->gain     = oracle_in_dp(t, name, base + 24);
    g->tcgf     = (agc_sp_t) oracle_in(t, name, base + 26);
    g->tcgi     = (agc_sp_t) oracle_in(t, name, base + 27);
}

/**********************************************************************
 * AGC: none -- fresh LM state and the inputs shared by the guidance
 * cases (targets, LEADTIME, MASS, WM).
 *
 * ARGUMENTS:
 *   t  const char *  I    case tag
 **********************************************************************/
static void common_in(const char *t)
{
    agc_lm_pad_t  *p = agc_lm_pad();          /* pad loads */
    agc_lm_ldg_t  *l = agc_lm_ldg();          /* landing erasables */
    agc_guid_lm_t *g = &agc_guid_state()->lm; /* LM guidance state */

    agc_state_init(AGC_VEHICLE_LM);
    (void) agc_exec_init();
    (void) agc_guid_init(AGC_VEHICLE_LM);
    agc_lm_landing_reset();
    target_in(t, "RBRFG", &p->target[0]);
    target_in(t, "RBRFG+28", &p->target[1]); /* RAPFG .. TCGIAPPR */
    p->leadtime = (agc_sp_t) oracle_in(t, "LEADTIME", 0);
    g->mass     = oracle_in_dp(t, "MASS", 0);
    l->wm       = oracle_in_vec(t, "WM");
}

/**********************************************************************
 * RGVGCALC .. AFCCALC (pp. 805-810): one guidance pass against the
 * rope.
 *
 * ARGUMENTS:
 *   t    const char *  I    case tag
 *   tol  long int      I    tolerance of the state words, LSB
 **********************************************************************/
static void guid_pass(const char *t, long int tol)
{
    agc_interp_t   ip;                        /* interpreter state (OVFIND) */
    agc_lm_ldg_t  *l = agc_lm_ldg();          /* landing erasables */
    agc_guid_lm_t *g = &agc_guid_state()->lm; /* LM guidance state */

    common_in(t);
    agc_interp_init(&ip);
    g->r                        = oracle_in_vec(t, "R");
    g->v                        = oracle_in_vec(t, "V");
    g->xnbpip.row[0]            = oracle_in_vec(t, "XNBPIP");
    g->xnbpip.row[2]            = oracle_in_vec(t, "ZNBPIP");
    agc_guid_state()->avg.gdt_2 = oracle_in_vec(t, "GDT/2");
    l->land                     = oracle_in_vec(t, "LAND");
    l->cg                       = mat_in(t, "CG");
    l->ttf_8                    = oracle_in_dp(t, "TTF/8", 0);
    l->ttf_8_hi                 = (agc_sp_t) oracle_in(t, "TTF/8", 0);
    l->wchphase                 = (agc_sp_t) oracle_in(t, "WCHPHASE", 0);
    l->flpass0                  = (agc_sp_t) oracle_in(t, "FLPASS0", 0);
    (void) agc_lm_rgvgcalc(&ip);
    (void) agc_lm_ttf8cl(&ip);
    (void) agc_lm_quadguid(&ip);
    oracle_require_ok(t, "CGCALC");
    oracle_cmp_vec(t, "ANGTERM", l->angterm, oracle_out_vec(t, "ANGTERM"), tol);
    oracle_cmp_vec(t, "VGU", l->vgu, oracle_out_vec(t, "VGU"), tol);
    (void) oracle_cmp(t, "VHORIZ", l->vhoriz, oracle_out_dp(t, "VHORIZ"), tol);
    oracle_cmp_vec(t, "RGU", l->rgu, oracle_out_vec(t, "RGU"), tol);
    (void) oracle_cmp(t, "RANGEDSP", l->rangedsp, oracle_out_dp(t, "RANGEDSP"), tol);
    (void) oracle_cmp(t, "LOOKANGL", l->lookangl, oracle_out_sp(t, "LOOKANGL"), 0);

    /* ROOTPSRS stops at |DX| <= TTF/8 * 2^-7: last-pass rounding moves the
     * root by a few hundred LSB. TTFDISP = 8 * high word of a DAS result
     * the AGC leaves sign-disagreeing (F9): one high-word LSB = 8.       */
    (void) oracle_cmp(t, "TTF/8", l->ttf_8, oracle_out_dp(t, "TTF/8"), 0);
    (void) oracle_cmp(t, "TTFDISP", l->ttfdisp, oracle_out_dp(t, "TTFDISP"), 0);
    (void) oracle_cmp(t, "TREDES", l->tredes, oracle_out_sp(t, "TREDES"), 0);

    /* QUADGUID coefficients: the AGC stores them as single words over
     * stale low words of the push list (guidance.c DEVIATION).           */
    oracle_cmp_vec(t, "UNFC/2", l->unfc_2, oracle_out_vec(t, "UNFC/2"), 128);
    (void) oracle_cmp(t, "/AFC/", l->afc, oracle_out_dp(t, "/AFC/"), 128);
    (void) oracle_cmp(t, "FLPASS0", l->flpass0, oracle_out_sp(t, "FLPASS0"), 0);
    (void) oracle_cmp(t, "WCHPHOLD", l->wchphold, oracle_out_sp(t, "WCHPHOLD"), 0);
} /* guid_pass */

/**********************************************************************
 * CGCALC (pp. 810-811) against the rope.
 *
 * ARGUMENTS:
 *   t    const char *  I    case tag
 *   tol  long int      I    tolerance of the CG words, LSB
 **********************************************************************/
static void cgcalc(const char *t, long int tol)
{
    agc_interp_t  ip;               /* interpreter state (OVFIND) */
    agc_lm_ldg_t *l = agc_lm_ldg(); /* landing erasables */

    common_in(t);
    agc_interp_init(&ip);
    agc_guid_state()->lm.r = oracle_in_vec(t, "R");
    l->land                = oracle_in_vec(t, "LAND");
    l->angterm             = oracle_in_vec(t, "ANGTERM");
    l->ttf_8               = oracle_in_dp(t, "TTF/8", 0);
    l->ttf_8_hi            = (agc_sp_t) oracle_in(t, "TTF/8", 0);
    l->wchphase            = (agc_sp_t) oracle_in(t, "WCHPHASE", 0);
    l->cg                  = mat_in(t, "CG");
    (void) agc_lm_cgcalc(&ip);
    oracle_require_ok(t, "EXTLOGIC");

    for (int r = 0; r < 3; r++)
    {
        char n[16]; /* erasable name of the row */
        char w[16]; /* comparison label */

        (void) snprintf(n, sizeof (n), (r == 0) ? "CG" : "CG+%d", 6 * r); /* row */
        (void) snprintf(w, sizeof (w), "CG[%d]", r);
        oracle_cmp_vec(t, w, l->cg.row[r], oracle_out_vec(t, n), tol);
    }
}

/**********************************************************************
 * THROTTLE (pp. 793-797) against the rope, word for word.
 *
 * ARGUMENTS:
 *   t  const char *  I    case tag
 **********************************************************************/
static void throttle(const char *t)
{
    agc_lm_ldg_t *l = agc_lm_ldg(); /* landing erasables */
    agc_lm_thr_t *h = agc_lm_thr(); /* throttle erasables */

    common_in(t);
    agc_lm_pad()->lowcrit       = (agc_sp_t) oracle_in(t, "LOWCRIT", 0);
    agc_lm_pad()->highcrit      = (agc_sp_t) oracle_in(t, "LOWCRIT", 1);
    agc_guid_state()->lm.abdelv = (agc_sp_t) oracle_in(t, "ABDELV", 0);
    l->afc                      = oracle_in_dp(t, "/AFC/", 0);
    l->thistpip                 = oracle_in_dp(t, "THISTPIP", 0);
    h->tthrot                   = (agc_sp_t) oracle_in(t, "TTHROT", 0);
    h->fweight.hi               = (agc_sp_t) oracle_in(t, "FWEIGHT", 0);
    h->fweight.lo               = (agc_sp_t) oracle_in(t, "FWEIGHT", 1);
    h->fcold                    = (agc_sp_t) oracle_in(t, "FCOLD", 0);
    agc_erase_set_modreg((agc_sp_t) oracle_in(t, "MODREG", 0));
    agc_erase_set_piptime(oracle_in_dp(t, "PIPTIME", 0));

    /* TIME1 as the AGC read it at DOIT (the emulated counter ticks once
     * while THROTTLE runs; the AGC stored that reading in TTHROT).       */
    agc_time_set_cs((uint32_t) oracle_out_sp(t, "TTHROT"));
    (void) agc_lm_throttle();
    oracle_require_ok(t, "ENDOFJOB");

    /* FP, FCODD, PIF, FWEIGHT: both words as the AGC stores them (a DAS
     * leaves them sign-disagreeing; THROTTLE reads the high word alone). */
    (void) oracle_cmp(t, "FP", agc_lm_words_value(h->fp), oracle_out_dp(t, "FP"), 0);
    (void) oracle_cmp(t, "FP hi", h->fp.hi, oracle_out_sp(t, "FP"), 0);
    (void) oracle_cmp(t, "FC", agc_dp_high(h->fc), oracle_out_sp(t, "FC"), 0);
    (void) oracle_cmp(t, "FCODD", agc_lm_words_value(h->fcodd), oracle_out_dp(t, "FCODD"), 0);
    (void) oracle_cmp(t, "FCOLD", h->fcold, oracle_out_sp(t, "FCOLD"), 0);
    (void) oracle_cmp(t, "PIF", agc_lm_words_value(h->pif), oracle_out_dp(t, "PIF"), 0);
    (void) oracle_cmp(t, "PIF hi", h->pif.hi, oracle_out_sp(t, "PIF"), 0);
    (void) oracle_cmp(t, "PIFPSET", h->pifpset, oracle_out_sp(t, "PIFPSET"), 0);
    (void) oracle_cmp(t, "PSEUDO55", h->pseudo55, oracle_out_sp(t, "PSEUDO55"), 0);
    (void) oracle_cmp(t, "THRUST", agc_erase_thrust(), oracle_out_sp(t, "THRUST"), 0);
    (void) oracle_cmp(t, "FWEIGHT", agc_lm_words_value(h->fweight), oracle_out_dp(t, "FWEIGHT"), 0);
    (void) oracle_cmp(t, "FWEIGHT hi", h->fweight.hi, oracle_out_sp(t, "FWEIGHT"), 0);
} /* throttle */

/**********************************************************************
 * FINDCDUW (pp. 910-918) against the rope (outside PNGCS auto).
 *
 * ARGUMENTS:
 *   t    const char *  I    case tag
 *   tol  long int      I    tolerance of CPHI..CPSI, LSB
 **********************************************************************/
static void findcduw(const char *t, long int tol)
{
    agc_interp_t   ip;                        /* interpreter state (OVFIND) */
    agc_guid_lm_t *g = &agc_guid_state()->lm; /* LM guidance state */
    agc_vec_t      unfc;                      /* thrust command UNFC/2 (MPAC), 2^1 */

    common_in(t);
    agc_interp_init(&ip);
    (void) agc_chan_set_input(AGC_CHAN_CHAN30, 037777); /* yaAGC power-up */
    (void) agc_chan_set_input(AGC_CHAN_CHAN31, 077777);
    agc_lm_initcduw();
    agc_lm_ldg()->unwc_2 = oracle_in_vec(t, "UNWC/2");
    g->xnbpip.row[0]     = oracle_in_vec(t, "XNBPIP");
    g->xnbpip.row[2]     = oracle_in_vec(t, "ZNBPIP");
    agc_erase_set_delv(oracle_in_vec(t, "DELV"));
    agc_erase_set_cdux(oracle_in_raw(t, "CDUX", 0));
    agc_erase_set_cduy(oracle_in_raw(t, "CDUX", 1));
    agc_erase_set_cduz(oracle_in_raw(t, "CDUX", 2));
    unfc.c[0]            = oracle_in_dp(t, "MPAC", 0);
    unfc.c[1]            = oracle_in_dp(t, "MPAC", 3);
    unfc.c[2]            = oracle_in_dp(t, "MPAC", 5);
    (void) agc_lm_findcduw(&ip, unfc);
    oracle_require_ok(t, "DSPLY81");

    for (int k = 0; k < 3; k++)
    {
        char n[16]; /* erasable name */

        (void) snprintf(n, sizeof (n), (k == 0) ? "CPHI" : "CPHI+%d", k); /* word */

        /* CPHI are two's-complement CDU words: compare the raw 15 bits
         * (read as ones' complement, a negative angle is one LSB off). */
        (void) oracle_cmp(t, n, (long int) (agc_erase_thetad(k) & 077777u), (long int) oracle_out_raw(t, n), tol);
    }
}

/**********************************************************************
 * ATMAG -> ASCENT -> P12RET (pp. 840-849): TBUP/AT from the 1/DV
 * filter, the ascent frame (YCOMP), MAINENG, RATES/CONST, CMPONENT,
 * AIMER, YAW and PITCH.
 * The DOT SL / DMP SL sites shift the TP MPAC (review-guid-landing).
 *
 * ARGUMENTS:
 *   t  const char *  I    case tag
 **********************************************************************/
static void ascent(const char *t)
{
    agc_guid_t   *g   = agc_guid_state(); /* guidance state */
    agc_lm_asc_t *a   = agc_lm_asc();     /* ascent erasables */
    agc_job_ctx_t ctx = {AGC_JOB_ATMAG, 020, false, -1, 0};

    agc_state_init(AGC_VEHICLE_LM);
    (void) agc_exec_init();
    (void) agc_dsky_init(); /* P12RET goes on into BURNBABY's display */
    (void) agc_guid_init(AGC_VEHICLE_LM);
    agc_lm_landing_reset();
    g->lm.abdvconv = oracle_in_dp(t, "ABDVCONV", 0);
    g->lm.mass1    = oracle_in_dp(t, "MASS1", 0);
    a->dv[1]       = oracle_in_dp(t, "E7,1634", 0);
    a->dv[2]       = oracle_in_dp(t, "E7,1636", 0);
    a->dv[3]       = oracle_in_dp(t, "E7,1640", 0);
    a->ve          = oracle_in_dp(t, "VE", 0);
    a->tbup        = oracle_in_dp(t, "TBUP", 0);
    a->tto         = oracle_in_dp(t, "TTO", 0);
    g->lm.r        = oracle_in_vec(t, "R");
    g->lm.v        = oracle_in_vec(t, "V");
    g->avg.unitr   = oracle_in_vec(t, "UNIT/R/");
    g->avg.gdt1_2  = oracle_in_vec(t, "GDT1/2");
    a->qaxis       = oracle_in_vec(t, "QAXIS");
    a->zaxis1      = oracle_in_vec(t, "ZAXIS1");
    a->rco         = oracle_in_dp(t, "RCO", 0);
    a->yco         = oracle_in_dp(t, "YCO", 0);
    a->tgo         = oracle_in_dp(t, "TGO", 0);
    a->zdotd       = oracle_in_dp(t, "ZDOTD", 0);
    a->ydotd       = oracle_in_dp(t, "YDOTD", 0);
    a->rdotd       = oracle_in_dp(t, "RDOTD", 0);
    g->lm.hdotdisp = oracle_in_dp(t, "HDOTDISP", 0);
    g->lm.xnbpip   = mat_in(t, "XNBPIP");
    g->lm.which    = AGC_LM_WHICH_POWERED_ASCENT;
    agc_flag_set(AGC_FLAG_FLPI);
    (void) agc_lm_job_atmag(&ctx);
    oracle_require_ok(t, "PHASCHNG");

    /* ATMAG's DSU 6SEC(18) and MAINENG's DSU TTO leave TBUP and TGO
     * sign-disagreeing (F9 class); AT (DDV by TBUP), TTOGO (SR 11D of
     * TGO) and every later DDV by TBUP or TGO see those words, which an
     * agc_dp_t cannot hold (ascent.c DEVIATION). Run from T2TEST with
     * the same values in canonical words, the rope gives exactly the C
     * PRATE..ATY; the tolerances cover the representation only.       */
    const struct
    {
        const char *name; /* erasable name in the case */
        agc_dp_t    got;  /* C value, scale 2^S of the word pair */
        long int    tol;  /* tolerance, LSB */
    } dps[] = { {"TBUP", a->tbup, 0}, {"AT", a->at, 4}, {"MASS1", g->lm.mass1, 0}, {"E7,1634", a->dv[1], 0}, {"E7,1636", a->dv[2], 0}, {"E7,1640", a->dv[3], 0}, {"/R/MAG", a->r_mag, 0}, {"ZDOT", a->zdot, 0}, {"YDOT", a->ydot, 0}, {"Y", a->y, 0}, {"GEFF", a->geff, 0}, {"DZDOT", a->dzdot, 0}, {"DYDOT", a->dydot, 0}, {"DRDOT", a->drdot, 0}, {"TGO", a->tgo, 0}, {"TTOGO", agc_erase_ttogo(), 1}, {"PRATE", a->prate, 32}, {"YRATE", a->yrate, 32}, {"PCONS", a->pcons, 4}, {"YCONS", a->ycons, 4}, {"ATR", a->atr, 8}, {"ATY", a->aty, 8}, {"ATP", a->atp, 8}, {"YAW", a->yaw, 8}, {"PITCH", a->pitch, 8} };

    for (size_t k = 0; k < sizeof (dps) / sizeof (dps[0]); k++)
    {
        (void) oracle_cmp(t, dps[k].name, dps[k].got, oracle_out_dp(t, dps[k].name), dps[k].tol);
    }

    oracle_cmp_vec(t, "LAXIS", a->laxis, oracle_out_vec(t, "LAXIS"), 0);
    oracle_cmp_vec(t, "VGVECT", a->vgvect, oracle_out_vec(t, "VGVECT"), 0);
    oracle_cmp_vec(t, "VGBODY", a->vgbody, oracle_out_vec(t, "VGBODY"), 0);
    oracle_cmp_vec(t, "UNFC/2", agc_lm_ldg()->unfc_2, oracle_out_vec(t, "UNFC/2"), 8);
    long int flpc = agc_flag_test(AGC_FLAG_FLPC) ? 1 : 0; /* C FLPC  */
    int      w9   = oracle_out_sp(t, "FLAGWRD9");         /* FLPC = bit 12 */
    long int want = ((w9 & 04000) != 0) ? 1 : 0;          /* rope's FLPC */

    (void) oracle_cmp(t, "FLPC", flpc, want, 0);
} /* ascent */

/**********************************************************************
 * RODCOMP (P66, pp. 816-819) up to THROTTLE +3: ROD clicks, PIPA
 * snapshot, HDOTDISP (DOT SL1 on the TP), HCALC1, /AFC/ (FWEIGHT DMP
 * BIT1H reads the high word of a sign-disagreeing pair), LASTTPIP.
 *
 * ARGUMENTS:
 *   t  const char *  I    case tag
 **********************************************************************/
static void rodcomp(const char *t)
{
    agc_guid_t   *g   = agc_guid_state(); /* guidance state */
    agc_lm_ldg_t *l   = agc_lm_ldg();     /* landing erasables */
    agc_lm_pad_t *p   = agc_lm_pad();     /* pad loads */
    agc_job_ctx_t ctx = {AGC_JOB_RODCOMP, 022, false, -1, 0};

    agc_state_init(AGC_VEHICLE_LM);
    (void) agc_exec_init();
    (void) agc_guid_init(AGC_VEHICLE_LM);
    agc_lm_landing_reset();
    l->rodcount = (agc_sp_t) oracle_in(t, "RODCOUNT", 0);
    l->rodscal1 = (agc_sp_t) oracle_in(t, "RODSCAL1", 0);
    l->vdgvert  = oracle_in_dp(t, "VDGVERT", 0);
    agc_erase_set_pipax((agc_sp_t) oracle_in(t, "PIPAX", 0));
    agc_erase_set_pipay((agc_sp_t) oracle_in(t, "PIPAX", 1));
    agc_erase_set_pipaz((agc_sp_t) oracle_in(t, "PIPAX", 2));

    for (int k = 0; k < 3; k++)
    {
        l->oldpipa[k]     = (agc_sp_t) oracle_in(t, "OLDPIPAX", k);
        g->avg.pipatmp[k] = (agc_sp_t) oracle_in(t, "PIPATMPX", k);
        agc_erase_set_tem(k, (agc_sp_t) oracle_in(t, "TEMX", k));
    }

    agc_time_set_cs((uint32_t) oracle_in(t, "TIME2", 1));
    agc_erase_set_piptime(oracle_in_dp(t, "PIPTIME", 0));
    l->lasttpip              = oracle_in_dp(t, "LASTTPIP", 0);
    g->avg.gdt_2             = oracle_in_vec(t, "GDT/2");
    l->vbias                 = oracle_in_vec(t, "VBIAS");
    g->lm.v                  = oracle_in_vec(t, "V");
    g->lm.r                  = oracle_in_vec(t, "R");
    l->land_mag              = oracle_in_dp(t, "/LAND/", 0);
    g->lm.hdotdisp           = oracle_in_dp(t, "HDOTDISP", 0);
    p->taurod                = oracle_in_dp(t, "TAUROD", 0);
    p->lag_tau               = oracle_in_dp(t, "LAG/TAU", 0);
    p->maxforce              = oracle_in_dp(t, "MAXFORCE", 0);
    p->minforce              = oracle_in_dp(t, "MINFORCE", 0);
    g->lm.mass               = oracle_in_dp(t, "MASS", 0);
    agc_lm_thr()->fweight.hi = (agc_sp_t) oracle_in(t, "FWEIGHT", 0);
    agc_lm_thr()->fweight.lo = (agc_sp_t) oracle_in(t, "FWEIGHT", 1);
    l->afc                   = oracle_in_dp(t, "/AFC/", 0);
    agc_erase_set_cdux(oracle_in_raw(t, "CDUX", 0));
    agc_erase_set_cduy(oracle_in_raw(t, "CDUX", 1));
    agc_erase_set_cduz(oracle_in_raw(t, "CDUX", 2));
    (void) agc_lm_job_rodcomp(&ctx);
    oracle_require_ok(t, "31,2221");
    (void) oracle_cmp(t, "VDGVERT", l->vdgvert, oracle_out_dp(t, "VDGVERT"), 0);
    (void) oracle_cmp(t, "THISTPIP", l->thistpip, oracle_out_dp(t, "THISTPIP"), 0);
    (void) oracle_cmp(t, "LASTTPIP", l->lasttpip, oracle_out_dp(t, "LASTTPIP"), 0);
    (void) oracle_cmp(t, "HDOTDISP", g->lm.hdotdisp, oracle_out_dp(t, "HDOTDISP"), 0);
    (void) oracle_cmp(t, "HCALC1", l->hcalc1, oracle_out_dp(t, "HCALC1"), 0);
    (void) oracle_cmp(t, "/AFC/", l->afc, oracle_out_dp(t, "/AFC/"), 0);

    for (int k = 0; k < 3; k++)
    {
        char n[16]; /* erasable name */

        (void) snprintf(n, sizeof (n), (k == 0) ? "DELVROD" : "DELVROD+%d", 2 * k); /* word */
        (void) oracle_cmp(t, n, agc_dp_high(l->delvrod.c[k]), oracle_out_sp(t, n), 0);
    }
} /* rodcomp */
